def backoff_delay(attempt, base=1, cap=60):
    """Delay in seconds for a given retry attempt, capped at `cap`.

    Grows as ``base * 2**attempt`` but never exceeds ``cap``.
    """
    if attempt < 0:
        raise ValueError("attempt must be non-negative")
